"""Tests for tools/gen_module.py renderers, pinned to the committed dumps."""
import os
import shutil
import tempfile
import unittest

from tools.gen_module import render_main, render_variables, render_outputs, render_readme, render_test, render_sample, render_versions, generate_module
from tools.tfschema import load_resource

EXPECTED_SEGMENT_GROUP_VARIABLES = '''\
# GENERATED by tools/gen_module.py from schemas/provider/zpa.json — do not edit.
# Regenerate: make generate

variable "items" {
  description = "zpa_segment_group instances, keyed by a stable identifier."
  type = map(object({
    name = string
    description = optional(string)
    enabled = optional(bool)
    microtenant_id = optional(string)
    applications = optional(list(object({
      id = optional(string)
    })))
  }))
}
'''


class RenderVariablesTest(unittest.TestCase):
    def test_segment_group_exact(self):
        rs = load_resource("zpa_segment_group")
        self.assertEqual(
            render_variables("zpa_segment_group", rs), EXPECTED_SEGMENT_GROUP_VARIABLES
        )

    def test_url_categories_properties(self):
        rs = load_resource("zia_url_categories")
        out = render_variables("zia_url_categories", rs)
        self.assertNotIn("category_id", out)   # computed-only excluded
        self.assertNotIn("\n    val ", out)
        self.assertIn("configured_name = optional(string)", out)
        self.assertIn("urls = optional(list(string))", out)
        self.assertIn("scopes = optional(set(object({", out)
        self.assertIn("url_keyword_counts = optional(list(object({", out)


EXPECTED_SEGMENT_GROUP_MAIN = '''\
# GENERATED by tools/gen_module.py from schemas/provider/zpa.json — do not edit.
# Regenerate: make generate

resource "zpa_segment_group" "this" {
  for_each = var.items

  name = each.value.name
  description = each.value.description
  enabled = each.value.enabled
  microtenant_id = each.value.microtenant_id

  dynamic "applications" {
    for_each = each.value.applications == null ? [] : each.value.applications
    content {
      id = applications.value.id
    }
  }
}
'''


class RenderMainTest(unittest.TestCase):
    def test_segment_group_exact(self):
        rs = load_resource("zpa_segment_group")
        self.assertEqual(
            render_main("zpa_segment_group", rs), EXPECTED_SEGMENT_GROUP_MAIN
        )

    def test_url_categories_properties(self):
        rs = load_resource("zia_url_categories")
        out = render_main("zia_url_categories", rs)
        self.assertIn('resource "zia_url_categories" "this"', out)
        self.assertIn('dynamic "scopes"', out)
        self.assertIn('dynamic "url_keyword_counts"', out)
        self.assertNotIn("category_id", out)  # computed-only never assigned

    def test_single_mode_block_wraps_in_list(self):
        fake = {
            "block": {
                "attributes": {"name": {"type": "string", "required": True}},
                "block_types": {
                    "settings": {
                        "nesting_mode": "single",
                        "block": {
                            "attributes": {"on": {"type": "bool", "optional": True}}
                        },
                    }
                },
            }
        }
        out = render_main("zia_fake", fake)
        self.assertIn(
            "for_each = each.value.settings == null ? [] : [each.value.settings]", out
        )


class RenderRestTest(unittest.TestCase):
    def test_outputs_exact(self):
        rs = load_resource("zpa_segment_group")
        out = render_outputs("zpa_segment_group", rs)
        self.assertIn('output "items" {', out)
        self.assertIn("value = zpa_segment_group.this", out)
        self.assertIn('output "name_to_id" {', out)
        self.assertIn(
            "value = { for k, v in zpa_segment_group.this : v.name => v.id }", out
        )

    def test_outputs_omits_name_map_without_name(self):
        fake = {"block": {"attributes": {"id": {"type": "string", "computed": True}}}}
        out = render_outputs("zia_fake", fake)
        self.assertNotIn("name_to_id", out)

    def test_readme_mentions_regeneration(self):
        rs = load_resource("zpa_segment_group")
        out = render_readme("zpa_segment_group", rs)
        self.assertIn("make generate", out)
        self.assertIn("zpa_segment_group", out)

    def test_sample_has_required_attrs_only(self):
        rs = load_resource("zpa_segment_group")
        sample = render_sample("zpa_segment_group", rs)
        self.assertEqual(sample, '{\n  "items": {\n    "example": {\n      "name": "example"\n    }\n  }\n}\n')

    def test_test_skeleton_uses_mock_provider(self):
        rs = load_resource("zpa_segment_group")
        out = render_test("zpa_segment_group", rs)
        self.assertIn('mock_provider "zpa" {}', out)
        self.assertIn("command = plan", out)
        self.assertIn("length(var.items) == 1", out)

    def test_versions_contains_provider_source(self):
        rs = load_resource("zpa_segment_group")
        out = render_versions("zpa_segment_group", rs)
        self.assertIn('source = "zscaler/zpa"', out)
        self.assertIn("required_providers", out)

    def test_versions_zia_source(self):
        rs = load_resource("zia_url_categories")
        out = render_versions("zia_url_categories", rs)
        self.assertIn('source = "zscaler/zia"', out)


class GenerateModuleTest(unittest.TestCase):
    def test_writes_all_files(self):
        with tempfile.TemporaryDirectory() as td:
            generate_module("zpa_segment_group", out_root=td, overrides_root=os.path.join(td, "none"), fmt=False)
            base = os.path.join(td, "zpa_segment_group")
            for fname in ("variables.tf", "versions.tf", "main.tf", "outputs.tf", "README.md"):
                self.assertTrue(os.path.exists(os.path.join(base, fname)), fname)
            self.assertTrue(os.path.exists(os.path.join(base, "tests", "defaults.tftest.hcl")))
            self.assertTrue(os.path.exists(os.path.join(base, "tests", "sample.auto.tfvars.json")))

    def test_override_replaces_main(self):
        with tempfile.TemporaryDirectory() as td:
            ov = os.path.join(td, "ov", "zpa_segment_group")
            os.makedirs(ov)
            with open(os.path.join(ov, "main.tf"), "w") as f:
                f.write("# OVERRIDE\n")
            generate_module("zpa_segment_group", out_root=os.path.join(td, "mod"), overrides_root=os.path.join(td, "ov"), fmt=False)
            with open(os.path.join(td, "mod", "zpa_segment_group", "main.tf")) as f:
                self.assertEqual(f.read(), "# OVERRIDE\n")

class GoldenTest(unittest.TestCase):
    GOLDENS = [
        ("zpa_segment_group", "variables.tf", "render_variables"),
        ("zpa_segment_group", "main.tf", "render_main"),
        ("zpa_segment_group", "outputs.tf", "render_outputs"),
        ("zpa_segment_group", "versions.tf", "render_versions"),
        ("zia_url_categories", "variables.tf", "render_variables"),
        ("zia_url_categories", "main.tf", "render_main"),
        ("zia_url_categories", "outputs.tf", "render_outputs"),
        ("zia_url_categories", "versions.tf", "render_versions"),
    ]

    def test_rendered_output_matches_blessed_goldens(self):
        if shutil.which("terraform") is None:
            self.skipTest("terraform not on PATH — generator goldens are authoring-side")
        import tools.gen_module as g
        for resource_type, fname, renderer in self.GOLDENS:
            path = os.path.join("tools", "tests", "fixtures", "gen", resource_type, fname)
            with open(path) as f:
                expected = f.read()
            rendered = g._fmt(getattr(g, renderer)(resource_type, load_resource(resource_type)))
            self.assertEqual(rendered, expected, "%s/%s drifted — make update-goldens after intentional changes" % (resource_type, fname))


class AllComputedBlockTest(unittest.TestCase):
    FAKE = {
        "block": {
            "attributes": {"name": {"type": "string", "required": True}},
            "block_types": {
                "user": {
                    "nesting_mode": "set",
                    "block": {
                        "attributes": {
                            "username": {"type": "string", "computed": True}
                        }
                    },
                }
            },
        }
    }

    def test_render_main_raises_on_all_computed_block(self):
        from tools.gen_module import render_main
        with self.assertRaises(ValueError):
            render_main("zpa_fake", self.FAKE)

    def test_render_variables_raises_on_all_computed_block(self):
        from tools.gen_module import render_variables
        with self.assertRaises(ValueError):
            render_variables("zpa_fake", self.FAKE)


if __name__ == "__main__":
    unittest.main()
